CREATE TEMP TABLE IF NOT EXISTS observation_projection_rebuild_cleared_outputs (
   output_provider TEXT NOT NULL,
   output_message_id TEXT NOT NULL,
   PRIMARY KEY(output_provider, output_message_id)
) WITHOUT ROWID;

CREATE TEMP TABLE IF NOT EXISTS observation_projection_output_state_meta (
    initialized INTEGER PRIMARY KEY CHECK(initialized = 1),
    data_version INTEGER NOT NULL CHECK(data_version >= 0),
    provenance_rowid INTEGER NOT NULL CHECK(provenance_rowid >= 0)
) WITHOUT ROWID;

CREATE VIRTUAL TABLE IF NOT EXISTS session_occurrences_fts USING fts5(
    index_text,
    content='session_occurrences',
    content_rowid='rowid'
);

CREATE VIRTUAL TABLE IF NOT EXISTS session_summary_nodes_fts USING fts5(
    summary_text,
    content='session_summary_nodes',
    content_rowid='rowid'
);

CREATE TEMP TABLE IF NOT EXISTS observation_projection_predecessor_cleared_outputs (
            output_provider TEXT NOT NULL,
            output_message_id TEXT NOT NULL,
            PRIMARY KEY(output_provider, output_message_id)
         ) WITHOUT ROWID;

CREATE TEMP TABLE IF NOT EXISTS observation_projection_rebuild_retained_outputs (
            output_provider TEXT NOT NULL,
            output_message_id TEXT NOT NULL,
            PRIMARY KEY(output_provider, output_message_id)
         ) WITHOUT ROWID;

CREATE VIRTUAL TABLE IF NOT EXISTS lcm_raw_messages_fts USING fts5(
        index_text, role, kind, model, tool_names,
        content='lcm_raw_messages',
        content_rowid='store_id'
    );

CREATE VIRTUAL TABLE IF NOT EXISTS memory_v2_assertion_payloads_fts USING fts5(
            content,
            content='memory_v2_assertion_payloads',
            content_rowid='rowid'
        );

